// Sector catalogue: 4 base sectors + 20 DLC sectors. Data lives in data/sectors.json
// (generated by tools/gen-sectors.js) so the store-text generator can read it too.

import data from './data/sectors.json';

export const BASE = data.base;
export const DLC = data.dlc;
export const SECTORS = Object.fromEntries([...BASE, ...DLC].map((s) => [s.key, s]));
export const BASE_KEYS = BASE.map((s) => s.key);
export const sectorByKey = (k) => SECTORS[k] || BASE[0];

// Which DLC (if any) a hat belongs to.
export function hatDlc(hat) {
  const d = DLC.find((x) => x.hat === hat);
  return d ? d.key : null;
}

// Sector for a given shift in a given mode.
//   'base'  -> walks through the four base sectors
//   'tour'  -> random pick from base sectors + every DLC sector the host owns
//   <key>   -> always that sector
export function pickSector(mode, shift, owned, rnd) {
  if (mode === 'base') return BASE_KEYS[Math.floor((shift - 1) / 2) % BASE_KEYS.length];
  if (mode === 'tour') {
    const pool = BASE_KEYS.concat(DLC.filter((d) => owned.has(d.key)).map((d) => d.key));
    return pool[Math.floor(rnd() * pool.length)];
  }
  const s = SECTORS[mode];
  if (!s) return BASE_KEYS[0];
  if (s.n && !owned.has(s.key)) return BASE_KEYS[0];
  return s.key;
}
